const context=$('Ngữ cảnh').item.json;
const raw=$json.output;
const actions=['CALL','SEND_EMAIL','OFFER_VIEWING','WAIT'];
const valid=raw && typeof raw==='object' && actions.includes(raw.action) && typeof raw.reason==='string';
const suggestion=valid?{action:raw.action,reason:raw.reason.slice(0,500),emailDraft:null}:{action:'CALL',reason:'Liên hệ trực tiếp để xác nhận nhu cầu khách.',emailDraft:null};
let dropped=false;
if(valid && raw.action!=='WAIT' && typeof raw.emailDraft==='string') {
 const text=raw.emailDraft.trim();
 // Fail closed for factual promises. Numbers/URLs/markup are excluded rather than guessing whether AI inferred them correctly.
 const unsafe=/[0-9]|https?:|www\.|<[^>]*>|giảm\s*giá|chiết\s*khấu|cam\s*kết|đảm\s*bảo|chắc\s*chắn|giá\s*(chỉ|tốt|ưu|bán|thuê)|pháp\s*lý|sổ\s*(đỏ|hồng)|nội\s*thất|hồ\s*bơi|bể\s*bơi|bàn\s*giao|miễn\s*phí|\b(tỷ|triệu|vnd|usd)\b/iu.test(text);
 // An AI-written greeting/question is safe; declarative factual text is left for the sale to write manually.
 const sentences=text.split(/[.!?\n]+/).map(s=>s.trim()).filter(Boolean);
 const permitted=[/^(xin )?chào (anh|chị|anh\/chị|quý khách)$/iu,/^(anh|chị|anh\/chị|quý khách) (còn nhu cầu tìm (nhà|bất động sản)|còn quan tâm|có muốn (trao đổi thêm|xem thêm căn khác)) (không|ạ)$/iu,/^vui lòng (phản hồi|liên hệ lại) để (em|chúng tôi) hỗ trợ$/iu,/^cảm ơn (anh|chị|anh\/chị|quý khách)$/iu];
 const questions=sentences.every(s=>permitted.some(pattern=>pattern.test(s)));
 if(text && text.length<=1500 && !unsafe && questions) suggestion.emailDraft=text;
 else dropped=true;
} else if(valid && raw.action!=='WAIT') dropped=true;
return {json:{context,suggestion,aiFailed:!valid,draftDropped:dropped}};
